rows.vgi.executable_examples:
[
  {
    "description": "A PowerShell -EncodedCommand string flags T1059.001.",
    "sql": "SELECT attack_id FROM disasm.main.capabilities('powershell.exe -EncodedCommand ZQA='::BLOB) WHERE attack_id = 'T1059.001' LIMIT 1"
  }
]

[
  {
    "description": "Disassemble x64 shellcode at an explicit base (0x1000); list its return sites.",
    "sql": "SELECT address, mnemonic, op_str FROM disasm.main.disassemble(from_hex('554889e5c3'), arch := 'x86', mode := 'x64', base := 4096) WHERE list_contains(groups, 'ret')"
  },
  {
    "description": "Count decoded instructions in a raw x64 nop sled.",
    "sql": "SELECT count(*) AS n FROM disasm.main.disassemble(from_hex('90909090'), arch := 'x86', mode := 'x64')"
  }
]

[
  {
    "description": "A raw (non-container) blob has no imports.",
    "sql": "SELECT count(*) AS n FROM disasm.main.imports('not a binary')"
  }
]

[
  {
    "description": "A raw (non-container) blob has no sections.",
    "sql": "SELECT count(*) AS n FROM disasm.main.sections('not a binary')"
  }
]

[
  {
    "description": "Extract ASCII strings (min length 4) from an inline blob.",
    "sql": "SELECT value FROM disasm.main.strings('hello world embedded text'::BLOB) WHERE encoding = 'ascii' ORDER BY \"offset\" LIMIT 1"
  }
]
